public int leastInterval(char[] tasks, int n) {
    int[] freq = new int[26];
    for (char c : tasks) freq[c - 'A']++;
    PriorityQueue<Integer> heap =
        new PriorityQueue<>(Collections.reverseOrder());
    for (int f : freq) if (f > 0) heap.offer(f);

    int time = 0;
    while (!heap.isEmpty()) {
        int cycle = n + 1;
        List<Integer> leftover = new ArrayList<>();
        int run = 0;
        while (cycle > 0 && !heap.isEmpty()) {
            int cur = heap.poll();
            if (cur - 1 > 0) leftover.add(cur - 1);
            run++;
            cycle--;
        }
        for (int rem : leftover) heap.offer(rem);
        // Full block (n+1) if tasks remain; else only what we ran.
        time += heap.isEmpty() ? run : n + 1;
    }
    return time;
}

